// TP : compteur de voyageurs à l’entrée d’une station.
// Barrière A côté rue (capteur OBS1), barrière B côté quai (OBS2) : leur sortie OUT passe à LOW
// quand quelqu’un est devant. A puis B : une entrée ; B puis A : une sortie.
const int BARRIERE_A = 2;
const int BARRIERE_B = 3;
const int LED_VERTE = 6;              // il reste de la place
const int LED_ROUGE = 7;              // station pleine
const int CAPACITE = 3;               // maquette : 3 voyageurs au plus
const unsigned long DELAI = 3000;     // ms pour atteindre la seconde barrière

int voyageurs = 0;                    // voyageurs dans la station
char premiere = '-';                  // barrière coupée en premier : 'A', 'B', '-' (aucune) ou 'X' (passage compté)
unsigned long debut = 0;              // instant où la première barrière a été coupée

void setup() {
  Serial.begin(9600);
  pinMode(BARRIERE_A, INPUT); // le module tient lui-même sa sortie (HIGH au repos)
  pinMode(BARRIERE_B, INPUT);
  pinMode(LED_VERTE, OUTPUT);
  pinMode(LED_ROUGE, OUTPUT);
  Serial.println("Compteur de voyageurs");
}

void loop() {
  bool a = digitalRead(BARRIERE_A) == LOW;
  bool b = digitalRead(BARRIERE_B) == LOW;

  if (premiere == '-') {
    // Personne en cours de passage : quelle barrière est coupée la première ?
    if (a) {
      premiere = 'A';
      debut = millis();
    } else if (b) {
      premiere = 'B';
      debut = millis();
    }
  } else if (premiere == 'A' && b) {
    voyageurs++;                      // A puis B : une entrée
    Serial.print("Entree, voyageurs : ");
    Serial.println(voyageurs);
    premiere = 'X';
  } else if (premiere == 'B' && a) {
    if (voyageurs > 0) voyageurs--;   // B puis A : une sortie
    Serial.print("Sortie, voyageurs : ");
    Serial.println(voyageurs);
    premiere = 'X';
  } else if (premiere != 'X' && millis() - debut > DELAI) {
    premiere = '-';                   // pas de seconde barrière : demi-tour, rien à compter
  }
  // Passage compté : on attend que les deux barrières soient libres.
  if (premiere == 'X' && !a && !b) premiere = '-';

  // Voyants : rouge quand la station est pleine, vert sinon.
  if (voyageurs >= CAPACITE) {
    digitalWrite(LED_ROUGE, HIGH);
    digitalWrite(LED_VERTE, LOW);
  } else {
    digitalWrite(LED_ROUGE, LOW);
    digitalWrite(LED_VERTE, HIGH);
  }
  delay(20);
}

text.fr:
Remplacez le test par le compteur. Variables globales : `int voyageurs = 0;`, `char premiere = '-';` (la barrière coupée en premier) et `unsigned long debut = 0;`. Dans loop() :
- `bool a = digitalRead(2) == LOW;` et `bool b = digitalRead(3) == LOW;` ;
- si `premiere == '-'` et qu’une barrière est coupée : `premiere` prend la valeur `'A'` ou `'B'`, et `debut = millis();` ;
- si `premiere == 'A'` et `b` : `voyageurs++` (une entrée) ; si `premiere == 'B'` et `a` : `voyageurs--` (une sortie, jamais sous 0). Affichez le compte au moniteur série, puis `premiere = 'X'` : on attend que les deux barrières soient libres pour revenir à `'-'` ;
- sans seconde barrière au bout de **3 s** (`millis() - debut > 3000`) : demi-tour, `premiere = '-'` ;
- si `voyageurs >= 3` (capacité de la maquette) : LED2 allumée et LED1 éteinte ; sinon l’inverse.
